#!/usr/bin/env python3
"""Раздел 1.5: UML-модели представления (по одной диаграмме каждого вида), без подразделов.
Блок диаграммы: краткий абзац со ссылкой, рисунок, описание. Порядок блоков и режим («рисунок – описание» или
«описание – рисунок») берутся из docs/kursovaya/src/layout-1.5.json (подбирает tune_layout.py), чтобы внизу страниц
не оставалось пустых мест. Раздел не заканчивается рисунком.
Использование: python3 build_15.py выход.docx
"""
import json, os, sys
import docx
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Builder

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
KURS = os.path.join(ROOT, 'docs', 'kursovaya')
FIRST = 13                                         # номер первого рисунка раздела 1.5
UNITS = {
    'uc': ('Функции системы с точки зрения внешних участников показаны на диаграмме вариантов использования (рисунок {n}).', 'uc', 'Диаграмма вариантов использования',
           'Актёры соответствуют участникам процесса из таблицы 1.2, варианты использования названы действиями. Клиент является специализацией гостя (обобщение) и наследует его возможности: гость смотрит курсы и регистрируется, клиент после проверки анкеты работает со счетами, переводами, платежами, вкладами, кредитами, картами и выписками. Отношение «include» показывает обязательные части действия: перевод и оплата услуги включают подтверждение операции кодом, оформление кредита включает оценку кредитоспособности и составление графика платежей, а рассмотрение заявки кредитным специалистом использует ту же оценку. Отношение «extend» показывает необязательное расширение при выполнении условия: конвертация валют, передача подозрительного перевода на проверку, досрочное закрытие вклада, досрочное погашение кредита, блокировка карты. Закрытие операционного дня администратором включает создание резервной копии.'),
    'seq': ('Последовательность оформления кредита показана на рисунке {n}.', 'seq-loan', 'Диаграмма последовательности: оформление кредита',
            'Объекты подписаны в форме «: Класс», клиент показан актёром, период работы объекта отмечен фокусом управления, сообщения пронумерованы и названы операциями программы. Клиент заполняет форму (fillForm), форма передаёт заявку контроллеру (create), и контроллер проверяет данные (validate). Ветвление показано отдельными блоками alt. Если данные некорректны, форма показывает ошибки (alt1). Иначе сервис скоринга (assess) читает кредитную историю и возвращает решение, после чего заявка сохраняется (saveApplication): при нагрузке выше 40 % или вероятности дефолта выше 30 % клиент видит отказ (alt2), иначе заявка одобрена или передана кредитному специалисту, и клиент видит её статус.'),
    'act': ('Порядок действий и их распределение между участниками показаны на рисунке {n}.', 'act-loan', 'Диаграмма деятельности: оформление кредита',
            'Диаграмма деятельности дополняет подраздел 1.2. Система рассчитывает график и долговую нагрузку: при нагрузке выше 40 % следует отказ. Затем скоринг определяет вероятность дефолта и направляет заявку по одной из ветвей: автоодобрение, ручное рассмотрение кредитным специалистом или отказ. После одобрения клиент подписывает договор кодом, и система выдаёт кредит: открывает ссудный счёт, формирует график и зачисляет деньги.'),
    'st': ('Состояния заявки на кредит показаны на рисунке {n}, названия состояний совпадают со значениями поля статуса в базе данных.', 'st-loan', 'Диаграмма состояний: заявка на кредит',
           'Заявка получает начальное состояние по результату проверки: approved при автоодобрении, manual_review при ручном рассмотрении, rejected при отказе. Специалист переводит заявку из manual_review в approved или rejected. Одобренная заявка после подписания договора кодом становится signed.'),
    'comp': ('Структура программного средства показана на диаграмме компонентов (рисунок {n}).', 'components', 'Диаграмма компонентов',
             'Браузер получает по HTTPS файлы интерфейса (страницу, таблицу стилей, модули JavaScript), затем обращается к программному интерфейсу сервера и получает данные в формате JSON. На сервере запрос проходит через промежуточные слои (сессии, защита от подделки запросов, проверка прав, двухфакторная защита), затем маршруты передают его контроллеру. Контроллер вызывает сервисы с бизнес-логикой и возвращает JSON, а страницы из него собирает клиентский JavaScript. Сервисы работают с базой данных MySQL через модели с SQL-запросами, получают курсы валют от Национального банка и отправляют письма через SMTP-сервер. Фоновые задачи создают зашифрованные резервные копии.'),
    'dep': ('Размещение программного средства на оборудовании показано на диаграмме развёртывания (рисунок {n}).', 'deployment', 'Диаграмма развёртывания',
            'Клиент работает в браузере и обращается к серверу приложения по протоколу HTTPS через обратный прокси-сервер с сертификатом TLS. Приложение на Node.js обращается к серверу базы данных MySQL, к почтовому серверу по SMTP и к Национальному банку за курсами валют.'),
}
DEFAULT_ORDER = ['uc', 'seq', 'act', 'st', 'comp', 'dep']
CLOSING = 'Построенные модели согласованы между собой и с подразделом 1.4: актёры и варианты использования соответствуют ролям и правам доступа, последовательность и состояния – статусам заявок в базе данных, компоненты – слоям программы.'


def layout():
    path = os.path.join(KURS, 'src', 'layout-1.5.json')
    if os.path.exists(path):
        return json.load(open(path, encoding='utf-8'))
    return {'order': DEFAULT_ORDER, 'modes': {}}


def build(out, lay=None):
    lay = lay or layout()
    d = docx.Document(os.path.join(KURS, 'src', 'er-part.docx'))
    P = d.paragraphs
    b = Builder(d, P[1], P[4], P[6])
    body = d.element.body
    for el in list(body):
        if not el.tag.endswith('sectPr'):
            body.remove(el)
    b.heading('1.5 UML-модели представления программного средства и их описание')
    b.para('Модели представления показывают программное средство с разных точек зрения: кто и для чего им пользуется, как взаимодействуют его части, в какой последовательности выполняются действия, какие состояния принимает объект и как система размещается на оборудовании. Для описания использован унифицированный язык моделирования UML, построено по одной диаграмме каждого вида. Диаграммы последовательности, деятельности и состояний посвящены оформлению кредита – наиболее сложному процессу системы (подраздел 1.2). Диаграмма классов и ER-диаграмма приведены в подразделе 1.4.')
    order = lay['order']
    for i, key in enumerate(order):
        lead, img, title, desc = UNITS[key]
        n = FIRST + i
        mode = 'A' if i == len(order) - 1 else lay['modes'].get(key, 'A')
        b.para(lead.format(n=f'1.{n}'))
        if mode == 'B':
            b.para(desc)
        b.figure(os.path.join(KURS, f'view-{img}.png'), f'Рисунок 1.{n} – {title}')
        if mode == 'A':
            b.para(desc)
    b.para(CLOSING)
    d.save(out)
    return {key: FIRST + i for i, key in enumerate(order)}


if __name__ == '__main__':
    build(sys.argv[1])
